async (page)=>{
const base='http://127.0.0.1:18762/final-preview-v4/';
const shot=async n=>page.screenshot({path:'Coursework/prototype/tether-final-build/qa-app/'+n+'.png',fullPage:true});
const click=async n=>page.locator(`[data-label="${n}"]`).first().click();
const input=n=>page.locator(`[data-label="${n}"] input, [data-label="${n}"] textarea`);
const wait=async f=>page.waitForURL('**/'+f+'.html*');
const has=async s=>{if(!await page.getByText(s,{exact:false}).count())throw Error('Missing '+s)};
await page.setViewportSize({width:430,height:932});
await page.goto(base+'00_welcome.html');await shot('01-welcome');
await click('app_login');await wait('01_log_in');await click('app_login');await has('Enter an email');
await input('login_email').fill('learner@example.test');await input('login_password').fill('example123');await shot('02-login');await click('app_login');await wait('04_today');await shot('03-dashboard');
await click('app_add');await wait('05_add_assignment');await input('assignment_title').fill('Digital wellbeing essay');await input('assignment_brief').fill('Compare two studies and explain how daily screen habits affect student wellbeing.');await shot('04-assignment');await click('app_review');await wait('06_check_requirements');if(!(await input('review_requirements').inputValue()).includes('daily screen habits'))throw Error('Requirements missing');await shot('05-review');
await click('app_build');await wait('07_your_plan');await has('Digital wellbeing essay');await input('plan_step_2').fill('Compare two studies about screen habits');await shot('06-plan');await click('personalized_start_2');await wait('02_continue_your_work');await has('Compare two studies about screen habits');
await click('hit_stuck');await wait('03_when_you_are_stuck');await click('v2_choice_small');await click('v2_try_suggestion');await wait('02_continue_your_work');await has('Write just the first line');
await click('hit_pause');await wait('04_leave_a_thread');await input('where_stopped').fill('Compared the first study');await input('next_move').fill('Find the second study');await click('hit_save_with_variables');await wait('05_ready_to_return');await click('hit_home');await wait('page_1');await has('Compared the first study');await has('Find the second study');await shot('07-saved-thread');await click('app_dashboard');await wait('04_today');await has('Digital wellbeing essay');await has('Find the second study');
await click('app_nav_plan');await wait('07_your_plan');if(await input('plan_step_2').inputValue()!=='Compare two studies about screen habits')throw Error('Step edit lost');await input('plan_step_1').fill('Read my assignment requirements');await click('personalized_schedule');await wait('08_study_time');await click('app_evening');await shot('08-schedule');await click('app_save');await wait('09_study_time_saved');await has('19:00');await has('Digital wellbeing essay');await shot('09-scheduled');await click('app_change');await wait('08_study_time');await has('19:00');await click('app_back');await wait('07_your_plan');if(await input('plan_step_1').inputValue()!=='Read my assignment requirements')throw Error('Plan edits lost on scheduling');
await click('app_nav_settings');await wait('10_your_space');await click('app_pace');await wait('03_set_your_pace');await click('app_steady');await has('Selected: Some room');await click('app_continue');await wait('04_today');await click('app_nav_settings');await wait('10_your_space');await has('Some room to focus');await shot('10-settings');await click('app_logout');await wait('00_welcome');await click('app_start');await wait('02_create_account');await click('app_signup');await has('Enter your first name');await input('signup_name').fill('Alex');await input('signup_email').fill('alex@example.test');await input('signup_password').fill('sample123');await shot('11-signup');await click('app_signup');await wait('03_set_your_pace');
return {ok:true,viewport:'430x932',flows:['login validation','custom assignment review','editable steps','get unstuck','saved context','dashboard live values','study time retained','study pace','signup validation']};
}
